// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.util.concurrent.atomic.AtomicInteger;

import org.junit.jupiter.api.Test;

/**
 * End-to-end probe-execution invariants at the arbiter level with scripted openers: one bounded probe of an uncertain
 * rival, timeout recorded as right-censored evidence (never a completion), fallback to the incumbent inside the same
 * dispatch, cooldown preventing an immediate re-probe, the ledger charged for the trial, and a fast trial winning its
 * probe outright.
 */
class LmdbNativeProbeExecutionTest {

	private static final double INCUMBENT_NANOS = 5_000_000.0; // 5 ms: deadline = 4 ms, spin stays short

	private record Fixture(LmdbNativeStoreCostModel store, LmdbNativeAdaptiveCostModel model,
			LmdbNativeStrategyProposal<String> incumbentTemplate) {
	}

	private static Fixture fixture() {
		LmdbNativeStoreCostModel store = new LmdbNativeStoreCostModel();
		LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(), store,
				new LmdbNativeAdaptiveCostModel.Configuration(true, true));
		LmdbNativeStrategyProposal<String> template = incumbentProposal(new AtomicInteger());
		LmdbNativeCostEstimate estimate = template.adaptiveEstimate(-1D);
		for (int i = 0; i < 30; i++) {
			model.recordCompleted(estimate, estimate.total(), INCUMBENT_NANOS, 1.0, model.currentRegime());
		}
		store.safetyLedger().earn(1_000_000_000_000L);
		return new Fixture(store, model, template);
	}

	private static LmdbNativeStrategyProposal<String> incumbentProposal(AtomicInteger opens) {
		return new LmdbNativeStrategyProposal<>(() -> {
			opens.incrementAndGet();
			return "incumbent";
		}, LmdbNativeWork.exact(1_000D), LmdbNativeAttemptMetrics.PATH_BATCH, () -> {
		});
	}

	private static LmdbNativeStrategyProposal<String> spinningRival(AtomicInteger opens) {
		return new LmdbNativeStrategyProposal<>(() -> {
			opens.incrementAndGet();
			int tick = 0;
			while (true) {
				LmdbNativeProbeDeadline.poll(++tick); // throws once the probe deadline fires
			}
		}, LmdbNativeWork.UNKNOWN, LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, () -> {
		});
	}

	private static LmdbNativeStrategyProposal<String> fastRival(AtomicInteger opens) {
		return new LmdbNativeStrategyProposal<>(() -> {
			opens.incrementAndGet();
			return "rival";
		}, LmdbNativeWork.UNKNOWN, LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, () -> {
		});
	}

	private static String dispatch(Fixture fixture, LmdbNativeStrategyProposal<String> incumbent,
			LmdbNativeStrategyProposal<String> rival) throws IOException {
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter
				.<String>forModel(null, -1D, fixture.model())
				.probeHarness(LmdbNativeProbeHarness.blocking())) {
			arbiter.offer(() -> incumbent);
			arbiter.offer(() -> rival);
			return arbiter.select();
		}
	}

	@Test
	void aTimedOutProbeCensorsCoolsDownFallsBackAndIsNotImmediatelyRetried() throws IOException {
		Fixture fixture = fixture();
		AtomicInteger incumbentOpens = new AtomicInteger();
		AtomicInteger rivalOpens = new AtomicInteger();
		LmdbNativeStrategyProposal<String> rival = spinningRival(rivalOpens);
		LmdbNativeCostEstimate rivalEstimate = rival.directTimingEstimate();
		long before = fixture.store().safetyLedger().availableNanos();

		String result = dispatch(fixture, incumbentProposal(incumbentOpens), rival);

		assertEquals("incumbent", result, "timeout + fallback yields exactly the incumbent's result");
		assertEquals(1, rivalOpens.get(), "the rival ran exactly once, bounded by the deadline");
		LmdbNativeRegimeKey regime = fixture.model().currentRegime();
		LmdbNativeCostPosteriorStore.ExactKey key = LmdbNativeCostPosteriorStore.ExactKey.of(regime,
				LmdbNativeCostPosteriorStore.Lane.DIRECT, rivalEstimate.variantKey());
		LmdbNativeCostPosteriorStore.Reading reading = fixture.store()
				.posteriors()
				.read(key, 0L,
						fixture.store().nowMillis());
		assertEquals(1, reading.exact().censoredCount, "the timeout is right-censored evidence");
		assertEquals(0, reading.exact().completedCount, "a timeout is never recorded as a completion");
		assertFalse(fixture.store().probeScheduler().mayProbe(rivalEstimate.variantKey(), regime, 0L),
				"one censor fulfills the obligation and starts the cooldown");
		assertTrue(fixture.store().safetyLedger().availableNanos() < before,
				"the trial's actual cost was charged to the ledger");

		// the very next matching dispatch must not probe the cooled-down arm
		String second = dispatch(fixture, incumbentProposal(incumbentOpens),
				spinningRival(rivalOpens));
		assertEquals("incumbent", second);
		assertEquals(1, rivalOpens.get(), "no immediate re-probe of a censored arm");
	}

	@Test
	void aCompletingProbePublishesTheTrialAndPricesTheArm() throws IOException {
		Fixture fixture = fixture();
		AtomicInteger rivalOpens = new AtomicInteger();
		LmdbNativeStrategyProposal<String> rival = fastRival(rivalOpens);
		LmdbNativeCostEstimate rivalEstimate = rival.directTimingEstimate();

		String result = dispatch(fixture, incumbentProposal(new AtomicInteger()), rival);

		assertEquals("rival", result, "a probe that completes within its deadline is published as the winner");
		assertEquals(1, rivalOpens.get());
		LmdbNativeRegimeKey regime = fixture.model().currentRegime();
		LmdbNativeCostPosteriorStore.ExactKey key = LmdbNativeCostPosteriorStore.ExactKey.of(regime,
				LmdbNativeCostPosteriorStore.Lane.DIRECT, rivalEstimate.variantKey());
		assertEquals(1, fixture.store().posteriors().read(key, 0L, fixture.store().nowMillis()).exact().completedCount,
				"the completion priced the previously ordinal arm");
		assertNotNull(fixture.model().predict(rivalEstimate).components(),
				"the arm is numerically comparable from its first completed probe on");
	}
}
